public int subarraysWithKDistinct(int[] nums, int k) {
    return atMost(nums, k) - atMost(nums, k - 1);
}

private int atMost(int[] nums, int k) {
    if (k < 0) return 0;
    Map<Integer, Integer> freq = new HashMap<>();
    int left = 0, res = 0;
    for (int right = 0; right < nums.length; right++) {
        if (freq.merge(nums[right], 1, Integer::sum) == 1) k--;
        while (k < 0) {
            if (freq.merge(nums[left], -1, Integer::sum) == 0) k++;
            left++;
        }
        res += right - left + 1;
    }
    return res;
}

public int countRangeSum(int[] nums, int lower, int upper) {
    long[] prefix = new long[nums.length + 1];
    for (int i = 0; i < nums.length; i++) prefix[i + 1] = prefix[i] + nums[i];
    return mergeCount(prefix, 0, prefix.length - 1, lower, upper, new long[prefix.length]);
}

private int mergeCount(long[] sum, int lo, int hi, int lower, int upper, long[] tmp) {
    if (lo >= hi) return 0;
    int mid = (lo + hi) >>> 1;
    int count = mergeCount(sum, lo, mid, lower, upper, tmp)
              + mergeCount(sum, mid + 1, hi, lower, upper, tmp);
    int j = mid + 1, k = mid + 1;
    for (int i = lo; i <= mid; i++) {
        while (j <= hi && sum[j] - sum[i] < lower) j++;
        while (k <= hi && sum[k] - sum[i] <= upper) k++;
        count += k - j;
    }
    int t = lo, p = lo, q = mid + 1;
    while (p <= mid && q <= hi) tmp[t++] = sum[p] <= sum[q] ? sum[p++] : sum[q++];
    while (p <= mid) tmp[t++] = sum[p++];
    while (q <= hi) tmp[t++] = sum[q++];
    System.arraycopy(tmp, lo, sum, lo, hi - lo + 1);
    return count;
}

public int[] maxSumOfThreeSubarrays(int[] nums, int k) {
    int n = nums.length;
    int[] sum = new int[n + 1];
    for (int i = 0; i < n; i++) sum[i + 1] = sum[i] + nums[i];
    int w = n - k + 1;                 // number of length-k windows
    int[] left = new int[w], right = new int[w];
    int best = 0;
    for (int i = 0; i < w; i++) {
        if (sum[i + k] - sum[i] > sum[best + k] - sum[best]) best = i;
        left[i] = best;
    }
    best = w - 1;
    for (int i = w - 1; i >= 0; i--) {
        if (sum[i + k] - sum[i] >= sum[best + k] - sum[best]) best = i;
        right[i] = best;
    }
    int[] res = {-1, -1, -1};
    int total = -1;
    for (int mid = k; mid <= n - 2 * k; mid++) {
        int l = left[mid - k], r = right[mid + k];
        int t = (sum[l + k] - sum[l]) + (sum[mid + k] - sum[mid]) + (sum[r + k] - sum[r]);
        if (t > total) { total = t; res = new int[]{l, mid, r}; }
    }
    return res;
}

public int numSubmatrixSumTarget(int[][] matrix, int target) {
    int rows = matrix.length, cols = matrix[0].length;
    for (int r = 0; r < rows; r++)
        for (int c = 1; c < cols; c++)
            matrix[r][c] += matrix[r][c - 1];   // horizontal prefix per row
    int res = 0;
    for (int c1 = 0; c1 < cols; c1++) {
        for (int c2 = c1; c2 < cols; c2++) {
            Map<Integer, Integer> count = new HashMap<>();
            count.put(0, 1);
            int prefix = 0;
            for (int r = 0; r < rows; r++) {
                prefix += matrix[r][c2] - (c1 > 0 ? matrix[r][c1 - 1] : 0);
                res += count.getOrDefault(prefix - target, 0);
                count.merge(prefix, 1, Integer::sum);
            }
        }
    }
    return res;
}

public int maxSumSubmatrix(int[][] matrix, int k) {
    int rows = matrix.length, cols = matrix[0].length;
    int best = Integer.MIN_VALUE;
    for (int c1 = 0; c1 < cols; c1++) {
        int[] rowSum = new int[rows];
        for (int c2 = c1; c2 < cols; c2++) {
            for (int r = 0; r < rows; r++) rowSum[r] += matrix[r][c2];
            TreeSet<Integer> set = new TreeSet<>();
            set.add(0);
            int prefix = 0;
            for (int s : rowSum) {
                prefix += s;
                Integer ceil = set.ceiling(prefix - k);
                if (ceil != null) best = Math.max(best, prefix - ceil);
                set.add(prefix);
            }
        }
    }
    return best;
}

public boolean checkSubarraySum(int[] nums, int k) {
    Map<Integer, Integer> firstIndex = new HashMap<>();
    firstIndex.put(0, -1);
    int prefix = 0;
    for (int i = 0; i < nums.length; i++) {
        prefix += nums[i];
        int r = ((prefix % k) + k) % k;
        if (firstIndex.containsKey(r)) {
            if (i - firstIndex.get(r) >= 2) return true;
        } else {
            firstIndex.put(r, i);
        }
    }
    return false;
}

public int subarraysDivByK(int[] nums, int k) {
    int[] count = new int[k];
    count[0] = 1;
    int prefix = 0, res = 0;
    for (int x : nums) {
        prefix = ((prefix + x) % k + k) % k;
        res += count[prefix];
        count[prefix]++;
    }
    return res;
}

public int splitArray(int[] nums, int k) {
    int lo = 0, hi = 0;
    for (int x : nums) { lo = Math.max(lo, x); hi += x; }
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (canSplit(nums, k, mid)) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

private boolean canSplit(int[] nums, int k, int cap) {
    int pieces = 1, cur = 0;
    for (int x : nums) {
        if (cur + x > cap) {
            pieces++;
            cur = x;
            if (pieces > k) return false;
        } else {
            cur += x;
        }
    }
    return true;
}
